1	package release
2	
3	import (
4		"encoding/json"
5		"errors"
6		"fmt"
7		"os"
8		"path/filepath"
9		"sync"
10		"syscall"
11	)
12	
13	const (
14		stateFileName = "ledger.json"
15		lockFileName  = "ledger.lock"
16		stateVersion  = 1
17	)
18	
19	// Store 是一个本地配方批次台账，数据保存在调用方指定的目录中。
20	// 不同目录互相独立；多个 Store 可以安全并发提交（进程内互斥、进程间文件锁）。
21	type Store struct {
22		// dir 是打开时确定的绝对路径。即使传入相对目录，也在 Open 时按当时的
23		// 工作目录解析并固定下来：此后调用方切换进程工作目录，本对象的读取与
24		// 保存仍指向最初打开的位置，绝不会按新工作目录重新解释这个相对路径。
25		dir      string
26		lockFile *os.File
27		mu       sync.Mutex
28		state    *persistedState
29	}
30	
31	// Open 打开（或首次使用）位于 dir 的台账。
32	// 目录不存在时会创建；目录中没有台账文件时得到空台账；
33	// 台账文件已存在但没有任何内容（零字节，无论原本就是空文件还是使用中被截断）
34	// 时按损坏处理；已有台账文件无法读取、解析，存在两条配方编号与版本号
35	// 完全相同的配方记录，存在两条批次编号完全相同的批次记录，
36	// 任一已保存配方版本不包含任何物料（物料列表为空数组、null 或字段缺失，
37	// 即使名称、编号、版本号齐全且内容能正常解析；含尚未被任何批次引用的版本），
38	// 任一配方版本的任一物料每份克数不是正数，
39	// 任一配方版本内同一物料编号出现多次，
40	// 任一批次绑定的配方版本未登记，
41	// 任一批次的状态不是精确的 "draft"、"executing"、"closed" 之一
42	// （缺失、为空、null、其他字符串，或大小写、前后空格与合法值不同），
43	// 任一批次的计划份数不是正整数，或按其绑定的配方版本计算时某物料的
44	// 应投量（每份克数 × 计划份数）无法精确表示到千分之一克或超过
45	// 9223372036854775.807 克，
46	// 任一批次仍为草稿状态却带有投料记录，
47	// 任一批次已保存投料的登记序号与记录在列表中的位置不一致
48	// （第一条不为 1、零或负数、重号、漏号、跳号，或调换记录位置后
49	// 未同步序号；不同物料共用批次序号、不同批次各自从 1 开始），
50	// 已保存投料的物料编号不属于该批次绑定的配方版本，
51	// 或已保存的投料数量非法（单条不是正数，或同一批次同一物料累计实投
52	// 超过 9223372036854775.807 克）时，返回 ErrCorruptData（可用 errors.Is
53	// 判断），不会当成空台账继续保存，也不会返回可继续使用的台账对象。
54	//
55	// dir 可以是相对目录：其位置只按 Open 调用时的工作目录解析一次并固定。
56	// 打开之后即使进程切换了工作目录，本对象的查询与保存仍始终指向最初打开
57	// 的目录，不会按新工作目录重新解释相对路径；台账操作本身也不会改变调用
58	// 方的工作目录。切换工作目录后另行 Open 同一相对目录，得到的是绑定新位
59	// 置的独立对象，与此前的对象互不影响。
60	func Open(dir string) (*Store, error) {
61		if dir == "" {
62			return nil, errors.New("数据位置不能为空")
63		}
64		// 先按“打开那一刻”的工作目录把位置解析成绝对路径并固定。后续每次
65		// 查询与写入都会重新读取台账文件，若仍持有相对路径，调用方一旦切换
66		// 工作目录，相对路径就会指向别处——可能把已登记批次查成不存在，或把
67		// 变更读写到另一个同名台账。解析为绝对路径后，本对象始终绑定最初打
68		// 开的位置。filepath.Abs 只做词法解析、不访问文件系统，目录尚不存在
69		// （首次使用会自动创建）时也能得到稳定结果。
70		absDir, err := filepath.Abs(dir)
71		if err != nil {
72			return nil, fmt.Errorf("解析数据位置 %q 失败: %w", dir, err)
73		}
74		if err := os.MkdirAll(absDir, 0o755); err != nil {
75			return nil, fmt.Errorf("创建数据位置 %q 失败: %w", absDir, err)
76		}
77		info, err := os.Stat(absDir)
78		if err != nil {
79			return nil, fmt.Errorf("读取数据位置 %q 失败: %w", absDir, err)
80		}
81		if !info.IsDir() {
82			return nil, fmt.Errorf("数据位置 %q 不是目录", absDir)
83		}
84	
85		lockPath := filepath.Join(absDir, lockFileName)
86		lf, err := os.OpenFile(lockPath, os.O_CREATE|os.O_RDWR, 0o644)
87		if err != nil {
88			return nil, fmt.Errorf("打开锁文件失败: %w", err)
89		}
90	
91		s := &Store{dir: absDir, lockFile: lf}
92		if err := s.load(); err != nil {
93			lf.Close()
94			return nil, err
95		}
96		return s, nil
97	}
98	
99	// Close 释放台账占用的文件锁。
100	func (s *Store) Close() error {
101		s.mu.Lock()
102		defer s.mu.Unlock()
103		if s.lockFile == nil {
104			return nil
105		}
106		err := s.lockFile.Close()
107		s.lockFile = nil
108		return err
109	}
110	
111	func (s *Store) lockExclusive() error {
112		if s.lockFile == nil {
113			return errors.New("台账已关闭")
114		}
115		if err := syscall.Flock(int(s.lockFile.Fd()), syscall.LOCK_EX); err != nil {
116			return fmt.Errorf("锁定台账失败: %w", err)
117		}
118		return nil
119	}
120	
121	func (s *Store) lockShared() error {
122		if s.lockFile == nil {
123			return errors.New("台账已关闭")
124		}
125		if err := syscall.Flock(int(s.lockFile.Fd()), syscall.LOCK_SH); err != nil {
126			return fmt.Errorf("锁定台账失败: %w", err)
127		}
128		return nil
129	}
130	
131	func (s *Store) unlock() {
132		_ = syscall.Flock(int(s.lockFile.Fd()), syscall.LOCK_UN)
133	}
134	
135	func (s *Store) load() error {
136		data, err := os.ReadFile(filepath.Join(s.dir, stateFileName))
137		if err != nil {
138			if os.IsNotExist(err) {
139				s.state = &persistedState{Version: stateVersion, Requests: map[string]*requestRecord{}}
140				return nil
141			}
142			return fmt.Errorf("%w: 读取台账文件失败: %v", ErrCorruptData, err)
143		}
144		if len(data) == 0 {
145			// 区分“没有台账文件”与“已有文件但内容为空”：文件不存在才算首次使用，
146			// 零字节文件（原本就为空或使用中被截断）一律按损坏处理——既不能当成
147			// 空台账补写，也不能凭内存中的旧记录还原，调用方必须明确知道无法读取。
148			return fmt.Errorf("%w: 台账文件 %q 没有内容", ErrCorruptData, filepath.Join(s.dir, stateFileName))
149		}
150		var st persistedState
151		if err := json.Unmarshal(data, &st); err != nil {
152			return fmt.Errorf("%w: 台账文件解析失败: %v", ErrCorruptData, err)
153		}
154		if st.Version != stateVersion {
155			return fmt.Errorf("%w: 台账版本 %d 不受支持", ErrCorruptData, st.Version)
156		}
157		if err := validateState(&st); err != nil {
158			return err
159		}
160		if st.Requests == nil {
161			st.Requests = map[string]*requestRecord{}
162		}
163		s.state = &st
164		return nil
165	}
166	
167	// validateState 检查台账的引用完整性与数量合法性：
168	//   - 配方由配方编号与版本号共同识别，同一台账内每组编号+版本号只能
169	//     对应一条配方记录。只要同组出现第二条记录，无论名称、物料、每份克数
170	//     是否相同（即使内容完全一致），整份台账即视为损坏：不能挑第一条或
171	//     最后一条、不能合并物料、也不能自行删除一条后继续——重复记录会让
172	//     查询结果与批次的应投依据取决于文件中的排列顺序。重复版本即使尚未
173	//     被任何批次引用也一样拒绝，其他配方与批次完整也不能放行本次读取。
174	//   - 批次由批次编号唯一识别，同一台账内一个编号只能对应一条批次记录。
175	//     同一编号出现第二条记录，无论绑定的配方版本、计划份数、状态是否
176	//     相同（即使内容完全一致），整份台账即视为损坏：不能挑第一条或最后
177	//     一条、不能合并投料、不能自动改号或删除一条后继续——重复记录会让
178	//     同一编号查到的配方、投料与数量核对取决于文件中的排列顺序。其他
179	//     批次完整、投料数量吻合，或调用方只想查看另一个正常批次，都不能
180	//     放行本次读取；不同编号的批次绑定同一配方版本不受影响。
181	//   - 每个已保存配方版本必须至少包含一种物料——与登记配方时的规则一致。
182	//     物料列表保存成空数组、null 或字段缺失，解析后都是空列表，属于同一
183	//     种损坏：没有物料就没有任何用量依据，采用它的批次得不到任何数量核对项。
184	//     任一版本（包括尚未被任何批次使用的版本）没有物料，整份台账即视为
185	//     损坏，即使其名称、编号与版本号齐全、台账内容能正常解析也不能接受：
186	//     不能补造物料、不能删除问题版本，也不能用同一配方编号下的其他完整
187	//     版本顶替。其他配方与批次完整、调用方只查询正常记录，或采用该版本
188	//     的批次份数为正、状态合法且尚未投料（没有任何数量差额），都不能放行。
189	//     没有登记任何配方的空台账与此不同，仍按空台账正常使用。
190	//   - 每个配方版本的每种物料，每份克数必须是正数——与登记时的规则一致。
191	//     任一版本（包括尚未被任何批次使用的版本）的任一物料为零或负数，
192	//     整份台账即视为损坏：不能改成最小用量、取绝对值、删除问题物料
193	//     或改用其他版本后继续，其他配方完整或批次数量恰好吻合也不能放行。
194	//   - 同一配方版本的物料列表内，每个物料编号只能出现一次——与登记时的
195	//     规则一致。任一版本（包括尚未被任何批次使用的版本）内同一物料编号
196	//     出现多次，整份台账即视为损坏：不能合并重复项、相加克数、丢弃其中
197	//     一条或由查询者挑一项作为依据，即使两条克数完全相同也不能放行；
198	//     不同版本、不同配方各自使用同一物料编号不受影响。
199	//   - 每个批次记录的配方编号与版本号必须共同指向一个已登记的配方版本。
200	//     任一批次找不到对应版本，整份台账即视为损坏——不能改用同编号的其他版本，
201	//     也不能按名称或物料内容替换，即使其他批次仍然完整也不能放行本次读取。
202	//   - 每个已保存批次的计划份数必须为正整数，且按该批次实际绑定的配方版本
203	//     计算，每种物料的应投量（每份克数 × 计划份数）都必须能精确表示到
204	//     千分之一克、且不超过 maxGramsMilli（9223372036854775.807 克）。
205	//     任一批次份数为零或负数，或任一物料的应投量无法精确表示/超出上限，
206	//     整份台账即视为损坏：不区分草稿、执行中还是已关闭，也不取决于本次
207	//     查询哪个批次——不能自动减少份数、改选其他配方版本或删除问题批次，
208	//     即使其他批次完整也不能放行。上限按每种物料分别判断：多种物料的
209	//     应投量相加超过上限不构成非法，单种物料恰好等于上限仍合法。
210	//   - 每个已保存批次的状态必须精确对应 draft、executing、closed 三个
211	//     字符串之一。状态字段缺失、为空或为 null，或保存成 "ready" 等其他
212	//     字符串，整份台账即视为损坏：不做大小写归一化，也不去除前后空格，
213	//     "Draft"、" draft " 与空字符串一样不合法。不能根据该批次有没有投料
214	//     替它猜一个状态、不能补成草稿，也不能删除该批次或跳过它继续返回
215	//     其他批次与配方——状态无法识别时，草稿带投料、状态机准入、查询
216	//     视图等所有依赖状态的规则都无从套用。即使配方版本与计划份数都正常、
217	//     尚未投料或投料数量恰好吻合，也不能放行；其他批次完整或本次只查询
218	//     别的批次、配方同样不能绕过。
219	//   - 草稿批次不能带有任何投料记录：登记投料只允许操作执行中的批次，
220	//     草稿尚未开始执行，出现投料说明保存内容自相矛盾。任一草稿批次包含
221	//     至少一条投料，整份台账即视为损坏——即使这些投料的物料都属于绑定
222	//     版本、克数均为合法正数、累计实投恰好等于应投，也不能接受；不能
223	//     丢弃投料后当作干净草稿，不能把批次自动改为执行中或已关闭，也不
224	//     能替调用方改选配方版本来继续读取。台账里另有正常批次、调用方只
225	//     查询其他配方或批次，都不能绕过这项矛盾。没有投料的草稿不受影响；
226	//     执行中尚未投料、已关闭批次没有投料或仍有欠投超投都属正常。
227	//   - 每条已保存的投料数量必须是正数；同一批次内同一物料的累计实投
228	//     不得超过 maxGramsMilli（9223372036854775.807 克）。任一记录为零或
229	//     负数，或任一物料累计超限，整份台账即视为损坏——负数记录即使能被
230	//     正数抵消回范围内也不接受，超限也不能截断或忽略后继续。
231	//   - 每个批次的投料按保存位置共用一条从 1 开始的登记序列：第一条序号
232	//     必须为 1，此后每条依次加 1，且保存序号必须与该记录在列表中的位置
233	//     一致。不同物料的投料共用同一序列、不按物料各自编号；不同批次各自
234	//     从 1 开始。任一条记录的序号为零或负数、与前一条不连续（漏号、
235	//     跳号）、与其他记录重号，或记录调换了位置却未同步序号，整份台账即
236	//     视为损坏：即使物料归属与数量全部合法也不能接受，不能按自带序号或
237	//     投料时间重排、不能补号、不能删除问题记录后继续。投料时间由调用方
238	//     填写、从不参与排序，时间相同或乱序不能作为序号有误的依据。空投料
239	//     列表不构成序号错误，仍按批次状态规则处理。
240	//   - 每条已保存投料的物料编号必须属于该批次绑定的配方版本。归属以批次
241	//     实际绑定的版本为准：物料只出现在同编号的其他版本或其他配方中，
242	//     不能作为接受依据；也不能改选版本、补入物料或丢弃问题投料后继续。
243	func validateState(st *persistedState) error {
244		// 先按“配方编号 + 版本号”唯一标识遍历全部配方记录：同组出现第二条
245		// 记录即数据损坏，必须先于一切按标识查找的校验拒绝——否则重复记录
246		// 会让 findRecipe 总是返回排在前面的一条，查询结果与批次应投依据都
247		// 取决于文件排列顺序。完全相同的内容也不是合法重复。
248		versions := make(map[recipeKey]bool, len(st.Recipes))
249		for _, r := range st.Recipes {
250			if r == nil {
251				return fmt.Errorf("%w: 台账中存在空的配方记录", ErrCorruptData)
252			}
253			key := recipeKey{r.RecipeNo, r.Version}
254			if versions[key] {
255				return fmt.Errorf("%w: 配方编号 %q 版本号 %q 的配方记录重复",
256					ErrCorruptData, r.RecipeNo, r.Version)
257			}
258			versions[key] = true
259		}
260		for _, r := range st.Recipes {
261			// 每个已保存配方版本必须至少包含一种物料——与登记配方时的规则一致：
262			// 没有物料就没有任何用量依据，采用它的批次得不到任何数量核对项。
263			// 物料列表保存成空数组、null 或字段缺失，解析后都是空列表，属于同一
264			// 种损坏。即使名称、编号、版本号齐全且台账内容能正常解析，也不能把
265			// 该版本当作有效配方：不能补造物料、不能删除问题版本，也不能改用同一
266			// 配方编号下的其他完整版本顶替。该校验针对所有已保存版本，包括尚未
267			// 被任何批次引用的版本；台账中另有正常配方与批次，或调用方只查询正常
268			// 记录，都不能绕过。必须先于逐条物料的校验判断——没有物料时，物料
269			// 编号重复与每份克数规则都无从套用。
270			if len(r.Materials) == 0 {
271				return fmt.Errorf("%w: 配方编号 %q 版本号 %q 的配方版本没有物料，每个配方版本必须至少包含一种物料",
272					ErrCorruptData, r.RecipeNo, r.Version)
273			}
274			seen := make(map[string]bool, len(r.Materials))
275			for _, m := range r.Materials {
276				if seen[m.MaterialNo] {
277					return fmt.Errorf("%w: 配方 %q 版本 %q 的物料编号 %q 重复",
278						ErrCorruptData, r.RecipeNo, r.Version, m.MaterialNo)
279				}
280				seen[m.MaterialNo] = true
281				if m.GramsMilli <= 0 {
282					return fmt.Errorf("%w: 配方 %q 版本 %q 物料 %q 的每份克数不是正数",
283						ErrCorruptData, r.RecipeNo, r.Version, m.MaterialNo)
284				}
285			}
286		}
287		// 再按批次编号唯一标识遍历全部批次记录：同一编号出现第二条记录即数据
288		// 损坏，必须先于一切按编号查找的校验拒绝——否则 findBatch 总是返回排在
289		// 前面的一条，同一编号查到的配方、投料与数量核对都取决于文件排列顺序。
290		// 两条记录即使绑定不同配方版本、计划份数不同或状态不同也属于重复；
291		// 内容完全一致同样不是合法记录。不能挑第一条或最后一条、不能合并投料、
292		// 也不能自动改号或删除一条后继续。不同批次绑定同一配方版本不受影响。
293		batchNos := make(map[string]bool, len(st.Batches))
294		for _, b := range st.Batches {
295			if b == nil {
296				return fmt.Errorf("%w: 台账中存在空的批次记录", ErrCorruptData)
297			}
298			if batchNos[b.BatchNo] {
299				return fmt.Errorf("%w: 批次编号 %q 的批次记录重复", ErrCorruptData, b.BatchNo)
300			}
301			batchNos[b.BatchNo] = true
302		}
303		for _, b := range st.Batches {
304			// 状态必须精确对应 draft、executing、closed 之一，且必须先于一切
305			// 依赖状态语义的校验（草稿带投料、状态机操作、查询视图）判断：
306			// 无法识别的状态没有任何既有规则可以套用。缺失、为空、null、写成
307			// "ready" 等其他字符串，或大小写不同、前后多了空格，都不能自动
308			// 当成某个合法状态——不能按是否已有投料替它猜状态，不能补成草稿，
309			// 也不能删除该批次后继续。只要一个批次状态不合法，整份台账即视为
310			// 损坏：其他批次与配方完整、本次只想查询别的批次或配方，都不能放行。
311			if !isValidBatchStatus(b.Status) {
312				if b.Status == "" {
313					return fmt.Errorf("%w: 批次 %q 的状态为空或缺失，必须是 %q、%q 或 %q 之一",
314						ErrCorruptData, b.BatchNo, StatusDraft, StatusExecuting, StatusClosed)
315				}
316				return fmt.Errorf("%w: 批次 %q 的状态 %q 无法识别，必须精确为 %q、%q 或 %q 之一（大小写或前后空格不同也不合法）",
317					ErrCorruptData, b.BatchNo, b.Status, StatusDraft, StatusExecuting, StatusClosed)
318			}
319			// 草稿尚未开始执行，不能登记投料；已保存的草稿却带着投料，
320			// 说明记录自相矛盾。必须先于配方归属与数量校验拒绝——否则
321			// 这份草稿还能被打开、调整份数或改选配方版本，留下按旧计划
322			// 登记的投料。不能丢弃投料当作干净草稿，不能自动改状态，也
323			// 不能改选版本后继续。
324			if b.Status == StatusDraft && len(b.Feedings) > 0 {
325				return fmt.Errorf("%w: 批次 %q 仍为草稿状态，却存在 %d 条投料记录",
326					ErrCorruptData, b.BatchNo, len(b.Feedings))
327			}
328			r := findRecipe(st, b.RecipeNo, b.RecipeVersion)
329			if r == nil {
330				return fmt.Errorf("%w: 批次 %q 绑定的配方 %q 版本 %q 未登记",
331					ErrCorruptData, b.BatchNo, b.RecipeNo, b.RecipeVersion)
332			}
333			if err := validateBatchPlan(b, r); err != nil {
334				return err
335			}
336			if err := validateFeedings(b, r); err != nil {
337				return err
338			}
339		}
340		return nil
341	}
342	
343	// validateBatchPlan 检查一个已保存批次的计划份数与按绑定配方版本算出的
344	// 应投量。数量规则本身（正份数、千分之一克精度、逐物料上限）统一由
345	// planRequirements 实现，这里只补充“读取已保存批次”场景的错误分类与
346	// 批次编号：份数非正或应投量非法都属于 ErrCorruptData。
347	// 归属以批次实际绑定的版本为准：换用同编号的其他版本或许能算得通，也
348	// 不能作为接受依据。计划数量是否合法与投料无关：尚未投料、实投不足或
349	// 超出应投都不影响。
350	func validateBatchPlan(b *batchRecord, r *recipeRecord) error {
351		if b.PlannedPortions <= 0 {
352			return fmt.Errorf("%w: 批次 %q 的计划份数 %d 不是正整数",
353				ErrCorruptData, b.BatchNo, b.PlannedPortions)
354		}
355		if _, err := planRequirements(r, b.PlannedPortions); err != nil {
356			return fmt.Errorf("%w: 批次 %q 的%v", ErrCorruptData, b.BatchNo, err)
357		}
358		return nil
359	}
360	
361	// validatePlanForRecipe 校验创建或调整草稿批次时，给定份数按配方版本逐
362	// 物料计算的应投量都能精确表示到千分之一克且不超过上限。份数本身的正
363	// 整数检查由调用方按各自输入规则完成（调整草稿时份数传 0 表示不改份数，
364	// 走到这里的必是最终采用的正份数）；数量规则统一由 planRequirements
365	// 实现，这里透传其逐物料说明（物料、配方编号、版本、份数），由调用方
366	// 按本次提交包装为 ErrInvalidInput。
367	func validatePlanForRecipe(r *recipeRecord, portions int) error {
368		_, err := planRequirements(r, portions)
369		return err
370	}
371	
372	// validateFeedings 检查一个批次内已保存投料的登记顺序、合法性与配方归属。
373	// 归属以批次绑定的配方版本 r 为准：每条投料的物料编号必须在 r 的物料
374	// 列表中，否则整份台账视为损坏。数量方面只判断数量本身是否合法，不判断
375	// 实投是否符合配方：无投料的物料累计为零属正常，不足或超过应投量也不
376	// 在此拒绝。
377	//
378	// 序号是整个批次共用的一条登记序列：不同物料的投料依次共用这组序号，
379	// 不按物料各自另起编号；不同批次则各自从 1 开始。列表中第 i 条（位置
380	// 从 1 起）的保存序号必须恰好为 i——第一条必须为 1，此后每条加 1。
381	// 零、负数、漏号、重号、跳号，或只调换了记录位置却没有同步序号，都说明
382	// 记录已经失去登记先后次序，整份台账视为损坏，即使物料归属与数量全部
383	// 合法也不能接受。投料时间只由调用方填写、从不参与排序，因此不能用来
384	// 佐证或否定序号：同一时刻登记、后一条时间早于前一条都属正常。该校验
385	// 只读取现有序号与位置，绝不重排、补号或删除任何投料。
386	func validateFeedings(b *batchRecord, r *recipeRecord) error {
387		acc := newFeedingAccumulator()
388		for i, f := range b.Feedings {
389			// 位置 i+1 上的保存序号必须就是 i+1：先于归属与数量校验判断，
390			// 因为一旦序号与位置不符，调用方已经无法按序号区分这是哪一次
391			// 成功登记——按错误的序号继续核对物料与数量没有意义。不能挑
392			// 记录自带的序号当真、不能按投料时间重排，也不能自行补号或
393			// 删除后继续。空投料列表不会进入这里，不构成序号错误。
394			pos := i + 1
395			if f.Seq != pos {
396				return fmt.Errorf("%w: 批次 %q 投料列表第 %d 条记录的登记序号为 %d，应为 %d：登记序号必须从 1 起按保存位置逐条连续加 1，不能为零或负数、重号、漏号、跳号或与位置不符",
397					ErrCorruptData, b.BatchNo, pos, f.Seq, pos)
398			}
399			belongs := false
400			for _, m := range r.Materials {
401				if m.MaterialNo == f.MaterialNo {
402					belongs = true
403					break
404				}
405			}
406			if !belongs {
407				return fmt.Errorf("%w: 批次 %q 的第 %d 条投料物料 %q 不属于其绑定的配方 %q 版本 %q",
408					ErrCorruptData, b.BatchNo, f.Seq, f.MaterialNo, b.RecipeNo, b.RecipeVersion)
409			}
410			if f.GramsMilli <= 0 {
411				return fmt.Errorf("%w: 批次 %q 物料 %q 的第 %d 条投料数量不是正数",
412					ErrCorruptData, b.BatchNo, f.MaterialNo, f.Seq)
413			}
414			if !acc.add(f.MaterialNo, f.GramsMilli) {
415				return fmt.Errorf("%w: 批次 %q 物料 %q 的累计实投超出上限 %s 克",
416					ErrCorruptData, b.BatchNo, f.MaterialNo, maxGramsMilli)
417			}
418		}
419		return nil
420	}
421	
422	// persist 先写临时文件再原子改名，并 fsync 目录，保证已提交数据可恢复。
423	func (s *Store) persist(st *persistedState) error {
424		data, err := json.MarshalIndent(st, "", "  ")
425		if err != nil {
426			return err
427		}
428		tmpPath := filepath.Join(s.dir, stateFileName+".tmp")
429		f, err := os.OpenFile(tmpPath, os.O_CREATE|os.O_WRONLY|os.O_TRUNC, 0o644)
430		if err != nil {
431			return err
432		}
433		if _, err := f.Write(data); err != nil {
434			f.Close()
435			return err
436		}
437		if err := f.Sync(); err != nil {
438			f.Close()
439			return err
440		}
441		if err := f.Close(); err != nil {
442			return err
443		}
444		if err := os.Rename(tmpPath, filepath.Join(s.dir, stateFileName)); err != nil {
445			return err
446		}
447		if d, err := os.Open(s.dir); err == nil {
448			_ = d.Sync()
449			_ = d.Close()
450		}
451		return nil
452	}
453	
454	func cloneState(st *persistedState) (*persistedState, error) {
455		data, err := json.Marshal(st)
456		if err != nil {
457			return nil, err
458		}
459		var out persistedState
460		if err := json.Unmarshal(data, &out); err != nil {
461			return nil, err
462		}
463		if out.Requests == nil {
464			out.Requests = map[string]*requestRecord{}
465		}
466		return &out, nil
467	}
468	
469	// write 是所有写入操作的统一入口：
470	//   - reqNo 为空直接报错；
471	//   - 同一 reqNo 且操作与内容完全相同，返回第一次成功的结果（幂等重放）；
472	//   - 同一 reqNo 用于其他操作或不同内容，返回 ErrRequestConflict；
473	//   - apply 在状态副本上执行，返回校验错误时不落盘、不占用请求编号；
474	//   - apply 成功后，状态与请求记录一起原子落盘，再切换到内存状态。
475	func (s *Store) write(reqNo, op string, payload any, apply func(*persistedState) (json.RawMessage, error), out any) error {
476		if reqNo == "" {
477			return errors.New("请求编号不能为空")
478		}
479		s.mu.Lock()
480		defer s.mu.Unlock()
481		if err := s.lockExclusive(); err != nil {
482			return err
483		}
484		defer s.unlock()
485	
486		// 跨进程场景下，其他进程可能已提交新数据；加锁后重新加载，
487		// 确保在最新状态上应用变更，避免用旧快照覆盖其他进程的写入。
488		if err := s.load(); err != nil {
489			return err
490		}
491	
492		payloadRaw, err := json.Marshal(payload)
493		if err != nil {
494			return err
495		}
496		payloadStr := string(payloadRaw)
497	
498		if req, ok := s.state.Requests[reqNo]; ok {
499			if req.Op != op || req.Payload != payloadStr {
500				return fmt.Errorf("%w: 请求编号 %q 已用于操作 %q，不能再用于操作 %q 或不同内容",
501					ErrRequestConflict, reqNo, req.Op, op)
502			}
503			if err := json.Unmarshal(req.Result, out); err != nil {
504				return fmt.Errorf("重放请求 %q 的结果失败: %w", reqNo, err)
505			}
506			return nil
507		}
508	
509		clone, err := cloneState(s.state)
510		if err != nil {
511			return err
512		}
513		result, err := apply(clone)
514		if err != nil {
515			return err
516		}
517		clone.Requests[reqNo] = &requestRecord{Op: op, Payload: payloadStr, Result: result}
518		if err := s.persist(clone); err != nil {
519			return fmt.Errorf("保存台账失败: %w", err)
520		}
521		s.state = clone
522		if err := json.Unmarshal(result, out); err != nil {
523			return fmt.Errorf("解析请求结果失败: %w", err)
524		}
525		return nil
526	}
527	
528	// read 在共享锁下读取当前状态。
529	func (s *Store) read(fn func(*persistedState) error) error {
530		s.mu.Lock()
531		defer s.mu.Unlock()
532		if err := s.lockShared(); err != nil {
533			return err
534		}
535		defer s.unlock()
536		if err := s.load(); err != nil {
537			return err
538		}
539		return fn(s.state)
540	}
541	
542	// 视图构造：每次都从记录全新构造，返回的切片与内部状态完全隔离。
543	
544	func buildRecipeView(r *recipeRecord) *RecipeView {
545		mats := make([]MaterialView, 0, len(r.Materials))
546		for _, m := range r.Materials {
547			mats = append(mats, MaterialView{MaterialNo: m.MaterialNo, Grams: m.GramsMilli.String()})
548		}
549		return &RecipeView{RecipeNo: r.RecipeNo, Version: r.Version, Name: r.Name, Materials: mats}
550	}
551	
552	func buildBatchView(b *batchRecord, r *recipeRecord) (*BatchView, error) {
553		v := &BatchView{
554			BatchNo:         b.BatchNo,
555			RecipeNo:        r.RecipeNo,
556			RecipeVersion:   r.Version,
557			RecipeName:      r.Name,
558			PlannedPortions: b.PlannedPortions,
559			Status:          b.Status,
560			Feedings:        make([]FeedingView, 0, len(b.Feedings)),
561			Materials:       make([]MaterialRequirement, 0, len(r.Materials)),
562		}
563	
564		for _, f := range b.Feedings {
565			v.Feedings = append(v.Feedings, FeedingView{
566				Seq:        f.Seq,
567				MaterialNo: f.MaterialNo,
568				Grams:      f.GramsMilli.String(),
569				Time:       f.Time,
570				Registrar:  f.Registrar,
571			})
572		}
573	
574		// 按物料累计实投量；台账在读取时已通过 validateFeedings 校验，
575		// 这里仍用同一套累计规则防一手整数回绕。
576		acc := newFeedingAccumulator()
577		for _, f := range b.Feedings {
578			if !acc.add(f.MaterialNo, f.GramsMilli) {
579				return nil, fmt.Errorf("%w: 批次 %q 物料 %q 的累计实投超出可表示范围",
580					ErrCorruptData, b.BatchNo, f.MaterialNo)
581			}
582		}
583	
584		// 数量核对按配方物料逐项列出；应投量统一由 planRequirements 按本批次
585		// 绑定版本与计划份数计算，与创建、调整、读取校验共用同一套规则。
586		// 台账在读取时已通过 validateState 校验，这里仍防一手同一版本内物料
587		// 编号重复，避免返回重复的数量核对项。
588		required, err := planRequirements(r, b.PlannedPortions)
589		if err != nil {
590			return nil, fmt.Errorf("%w: 批次 %q 的%v", ErrCorruptData, b.BatchNo, err)
591		}
592		seen := make(map[string]bool, len(required))
593		for _, item := range required {
594			if seen[item.materialNo] {
595				return nil, fmt.Errorf("%w: 配方 %q 版本 %q 的物料编号 %q 重复",
596					ErrCorruptData, r.RecipeNo, r.Version, item.materialNo)
597			}
598			seen[item.materialNo] = true
599			act := acc.total(item.materialNo)
600			v.Materials = append(v.Materials, MaterialRequirement{
601				MaterialNo:      item.materialNo,
602				RequiredGrams:   item.requiredGrams.String(),
603				ActualGrams:     act.String(),
604				DifferenceGrams: (act - item.requiredGrams).String(),
605			})
606		}
607		return v, nil
608	}
609	
610	// recipeKey 是配方的唯一标识：配方编号与版本号的组合，采用精确匹配。
611	type recipeKey struct {
612		recipeNo string
613		version  string
614	}
615	
616	func findRecipe(st *persistedState, recipeNo, version string) *recipeRecord {
617		for _, r := range st.Recipes {
618			if r.RecipeNo == recipeNo && r.Version == version {
619				return r
620			}
621		}
622		return nil
623	}
624	
625	func findBatch(st *persistedState, batchNo string) *batchRecord {
626		for _, b := range st.Batches {
627			if b.BatchNo == batchNo {
628				return b
629			}
630		}
631		return nil
632	}
