291	
292	// 两种拒绝必须区分：
293	//   - 沿用已成功的调整请求编号、却更改调整内容 → ErrRequestConflict；
294	//   - 换用尚未使用的请求编号、对已关闭批次提交相同内容 → ErrInvalidState。
295	// 两种拒绝都保留当前批次，且原成功请求仍可取得原结果。
296	func TestUpdateDraftReplayRejections(t *testing.T) {
297		s := openTestStore(t)
298		registerReplayRecipes(t, s)
299		if _, err := s.CreateBatch("b1", "B1", "R1", "v2", 5); err != nil {
300			t.Fatalf("创建批次失败: %v", err)
301		}
302		if _, err := s.UpdateDraftBatch("u-first", "B1", "R1", "v1", 8); err != nil {
303			t.Fatalf("第一次调整应成功: %v", err)
304		}
305		if _, err := s.UpdateDraftBatch("u-second", "B1", "R1", "v2", 3); err != nil {
306			t.Fatalf("第二次调整应成功: %v", err)
307		}
308		if _, err := s.StartBatch("s1", "B1"); err != nil {
309			t.Fatalf("开始执行失败: %v", err)
310		}
311		if _, err := s.CloseBatch("c1", "B1"); err != nil {
312			t.Fatalf("关闭批次失败: %v", err)
313		}
314	
315		// 同一请求编号、不同调整内容（改了份数）→ ErrRequestConflict。
316		if _, err := s.UpdateDraftBatch("u-first", "B1", "R1", "v1", 9); !errors.Is(err, ErrRequestConflict) {
317			t.Fatalf("同编号不同份数应返回 ErrRequestConflict，得到 %v", err)
318		}
319		// 同一请求编号、不同调整内容（改了配方版本）→ ErrRequestConflict。
320		if _, err := s.UpdateDraftBatch("u-first", "B1", "R1", "v2", 8); !errors.Is(err, ErrRequestConflict) {
321			t.Fatalf("同编号不同配方应返回 ErrRequestConflict，得到 %v", err)
322		}
323		// 新请求编号、相同内容，但批次已关闭 → ErrInvalidState。
324		if _, err := s.UpdateDraftBatch("u-fresh", "B1", "R1", "v1", 8); !errors.Is(err, ErrInvalidState) {
325			t.Fatalf("新编号对已关闭批次提交应返回 ErrInvalidState，得到 %v", err)
326		}
327	
328		// 两种拒绝都不改动当前批次：仍是已关闭的 R1/v2、3 份。
329		got, err := s.GetBatch("B1")
330		if err != nil {
331			t.Fatalf("查询批次失败: %v", err)
332		}
333		if got.RecipeNo != "R1" || got.RecipeVersion != "v2" || got.PlannedPortions != 3 ||
334			got.Status != StatusClosed {
335			t.Fatalf("拒绝后批次应保持已关闭的 R1/v2、3 份，得到 %+v", got)
336		}
337		mats := materialsMap(got)
338		checkRequirement(t, mats, "M1", "750", "0", "-750")
339		checkRequirement(t, mats, "M4", "6", "0", "-6")
340	
341		// 原成功请求仍可取得原结果。
342		replay, err := s.UpdateDraftBatch("u-first", "B1", "R1", "v1", 8)
343		if err != nil {
344			t.Fatalf("拒绝后原成功请求仍应可重放: %v", err)
345		}
346		checkFirstAdjustView(t, replay)
347	}
